// parseDays parses a duration that uses the unit d, by rewriting each number
// of days as hours. Go has no unit d, so any d in a valid value is a day unit.
func parseDays(v string) (time.Duration, error) {
	if !daysUnit.MatchString(v) {
		return 0, fmt.Errorf("no days in %q", v)
	}
	var bad error
	h := daysUnit.ReplaceAllStringFunc(v, func(m string) string {
		n, err := strconv.ParseFloat(strings.TrimSuffix(m, "d"), 64)
		if err != nil {
			bad = err
			return m
		}
		return strconv.FormatFloat(n*24, 'f', -1, 64) + "h"
	})
	if bad != nil {
		return 0, bad
	}
	return time.ParseDuration(h)
}

